    /**
     * Tests creating a new BIQuery.
     *
     * @return    BIQuery
     */
    public BIQuery testCreate() throws Throwable {
    BIQuery entity = null;

    LOGGER.info( "BIQueryTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a BIQuery");

    StringBuilder msg = new StringBuilder( "-- Failed to create a BIQuery" );

    try {
        entity = service.createBIQuery( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getBIQueryId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a BIQuery with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

