    /**
     * Tests getting all BIQuerys.
     *
     * @return    Collection
     */
    public List<BIQuery> testGetAll() throws Throwable {
    LOGGER.info( "BIQueryTest:testGetAll() - Retrieving Collection of BIQuerys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all BIQuery : " );
    List<BIQuery> collection  = null;

    try {
        // call the static get method on the BIQueryService
        collection = service.getAllBIQuery();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            BIQuery currEntity  = null;
            Iterator<BIQuery> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBIQueryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

